{"path": "/tmp/sv-e1cd863bf4514b60b2b7d565e49baf77/Components/Pages/Board/AddTaskForm.razor", "file_text": "@namespace sv_e1cd863bf4514b60b2b7d565e49baf77.Components.Pages.Board

<div class="add-task-form">
    <div class="form-group">
        <input type="text" @bind="title" placeholder="Title" class="form-input" />
    </div>
    <div class="form-group">
        <input type="text" @bind="assignee" placeholder="Assignee" class="form-input" />
    </div>
    <div class="form-group">
        <select @bind="priority" class="form-input">
            <option value="High">High</option>
            <option value="Medium">Medium</option>
            <option value="Low">Low</option>
        </select>
    </div>
    <div class="form-group">
        <input type="date" @bind="dueDate" class="form-input" />
    </div>
    <div class="form-actions">
        <button class="btn-save" @onclick="HandleSave" disabled="@isSaving">Save</button>
        <button class="btn-cancel" @onclick="HandleCancel" disabled="@isSaving">Cancel</button>
    </div>
    @if (!string.IsNullOrEmpty(errorMessage))
    {
        <p class="form-error">@errorMessage</p>
    }
</div>

@code {
    [Parameter, EditorRequired] public EventCallback<TaskItem> OnTaskCreated { get; set; }
    [Parameter, EditorRequired] public EventCallback OnCancel { get; set; }
    [Parameter, EditorRequired] public string ColumnStatus { get; set; } = "";
    [Parameter, EditorRequired] public ITaskService TaskService { get; set; } = default!;

    private string title = "";
    private string assignee = "";
    private string priority = "Medium";
    private DateTime dueDate = DateTime.Today.AddDays(7);
    private bool isSaving;
    private string? errorMessage;

    private async Task HandleSave()
    {
        if (string.IsNullOrWhiteSpace(title))
        {
            errorMessage = "Title is required.";
            return;
        }

        errorMessage = null;
        isSaving = true;
        try
        {
            var newTask = await TaskService.CreateTaskAsync(title, assignee, priority, dueDate);
            await OnTaskCreated.InvokeAsync(newTask);
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to create task: {ex.Message}";
        }
        finally
        {
            isSaving = false;
        }
    }

    private async Task HandleCancel()
    {
        await OnCancel.InvokeAsync();
    }
}
"}

{"path": "/tmp/sv-e1cd863bf4514b60b2b7d565e49baf77/Components/Pages/Board/KanbanColumn.razor", "file_text": "@namespace sv_e1cd863bf4514b60b2b7d565e49baf77.Components.Pages.Board

<div class="kanban-column">
    <div class="column-header">
        <h3>@ColumnName</h3>
        <span class="column-count">@Tasks.Count</span>
    </div>
    <div class="column-body">
        @foreach (var task in Tasks)
        {
            <TaskCard Task="task"
                      CanMoveLeft="CanMoveLeft"
                      CanMoveRight="CanMoveRight"
                      IsMoving="movingTaskId == task.Id"
                      OnMoveLeft="() => MoveTask(task, MoveDirection.Left)"
                      OnMoveRight="() => MoveTask(task, MoveDirection.Right)" />
        }
    </div>
    <div class="column-footer">
        @if (showAddForm)
        {
            <AddTaskForm ColumnStatus="@ColumnStatus"
                         TaskService="TaskService"
                         OnTaskCreated="HandleTaskCreated"
                         OnCancel="() => showAddForm = false" />
        }
        else
        {
            <button class="btn-add-task" @onclick="() => showAddForm = true">Add Task</button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string ColumnName { get; set; } = "";
    [Parameter, EditorRequired] public string ColumnStatus { get; set; } = "";
    [Parameter, EditorRequired] public List<TaskItem> Tasks { get; set; } = new();
    [Parameter] public bool CanMoveLeft { get; set; }
    [Parameter] public bool CanMoveRight { get; set; }
    [Parameter, EditorRequired] public string? LeftStatus { get; set; }
    [Parameter, EditorRequired] public string? RightStatus { get; set; }
    [Parameter, EditorRequired] public EventCallback<TaskItem> OnTaskCreated { get; set; }
    [Parameter, EditorRequired] public EventCallback OnTaskMoved { get; set; }
    [Parameter, EditorRequired] public ITaskService TaskService { get; set; } = default!;

    private bool showAddForm;
    private int? movingTaskId;

    private enum MoveDirection { Left, Right }

    private async Task MoveTask(TaskItem task, MoveDirection direction)
    {
        var newStatus = direction == MoveDirection.Left ? LeftStatus : RightStatus;
        if (newStatus is null) return;

        movingTaskId = task.Id;
        try
        {
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            await OnTaskMoved.InvokeAsync();
        }
        finally
        {
            movingTaskId = null;
        }
    }

    private async Task HandleTaskCreated(TaskItem task)
    {
        showAddForm = false;
        await OnTaskCreated.InvokeAsync(task);
    }
}
"}

