@page "/board"
@namespace sv_e1cd863bf4514b60b2b7d565e49baf77.Components.Pages.Board
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<div class="kanban-board">
    @if (isLoading)
    {
        <div class="board-loading">
            <p>Loading tasks...</p>
        </div>
    }
    else if (errorMessage is not null)
    {
        <div class="board-error">
            <p>@errorMessage</p>
            <button @onclick="LoadTasks">Retry</button>
        </div>
    }
    else
    {
        <BoardStats Tasks="allTasks" />
        <BoardSearchBar SearchTerm="@searchTerm" OnSearchChanged="HandleSearchChanged" />

        <div class="kanban-columns">
            <KanbanColumn ColumnName="To Do"
                          ColumnStatus="To Do"
                          Tasks="GetFilteredTasks("To Do")"
                          CanMoveLeft="false"
                          CanMoveRight="true"
                          LeftStatus="@null"
                          RightStatus="In Progress"
                          TaskService="TaskService"
                          OnTaskCreated="HandleTaskCreated"
                          OnTaskMoved="LoadTasks" />

            <KanbanColumn ColumnName="In Progress"
                          ColumnStatus="In Progress"
                          Tasks="GetFilteredTasks("In Progress")"
                          CanMoveLeft="true"
                          CanMoveRight="true"
                          LeftStatus="To Do"
                          RightStatus="Done"
                          TaskService="TaskService"
                          OnTaskCreated="HandleTaskCreated"
                          OnTaskMoved="LoadTasks" />

            <KanbanColumn ColumnName="Done"
                          ColumnStatus="Done"
                          Tasks="GetFilteredTasks("Done")"
                          CanMoveLeft="true"
                          CanMoveRight="false"
                          LeftStatus="In Progress"
                          RightStatus="@null"
                          TaskService="TaskService"
                          OnTaskCreated="HandleTaskCreated"
                          OnTaskMoved="LoadTasks" />
        </div>
    }
</div>

@code {
    private List<TaskItem> allTasks = new();
    private string searchTerm = "";
    private bool isLoading = true;
    private string? errorMessage;

    protected override async Task OnInitializedAsync()
    {
        await LoadTasks();
    }

    private async Task LoadTasks()
    {
        isLoading = true;
        errorMessage = null;
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private List<TaskItem> GetFilteredTasks(string status)
    {
        var tasks = allTasks.Where(t => t.Status == status);
        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            tasks = tasks.Where(t => t.Title.Contains(searchTerm, StringComparison.OrdinalIgnoreCase));
        }
        return tasks.ToList();
    }

    private void HandleSearchChanged(string value)
    {
        searchTerm = value;
    }

    private async Task HandleTaskCreated(TaskItem task)
    {
        await LoadTasks();
    }
}

